<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Journeys — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7fff4;--accent:#00b894;--muted:#264653;--card:#ffffff}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;color:#072227;background:var(--bg)}
    header{padding:12px 0;border-bottom:1px solid rgba(7,34,39,0.06);position:sticky;top:0;background:rgba(255,255,255,0.6);backdrop-filter:blur(4px);z-index:40}
    .wrap{max-width:1100px;margin:0 auto;padding:16px}
    .nav{display:flex;align-items:center;justify-content:space-between}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none}
    .hero{display:flex;gap:18px;align-items:center;padding:22px;border-radius:12px;background:linear-gradient(180deg,#fff,rgba(0,184,148,0.02));box-shadow:0 8px 24px rgba(2,48,43,0.04);overflow:hidden}
    .hero .left{flex:1}
    .hero h2{margin:0 0 8px 0}
    .kicker{display:inline-block;padding:6px 10px;border-radius:999px;background:rgba(0,184,148,0.08);color:var(--accent);font-weight:700}

    .programs{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:16px}
    .list{display:grid;gap:12px}
    .prog{padding:14px;border-radius:10px;background:var(--card);box-shadow:0 6px 18px rgba(2,48,43,0.03)}
    .meta{color:var(--muted);font-size:13px}
    .reveal{opacity:0;transform:translateY(16px);transition:opacity 480ms cubic-bezier(.2,.9,.2,1),transform 480ms cubic-bezier(.2,.9,.2,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (max-width:980px){.programs{grid-template-columns:1fr}} 

    /* small SVG accent */
    .pattern{width:100%;height:64px;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='400' height='64'><defs><linearGradient id='g3' x1='0' x2='1'><stop offset='0' stop-color='%2300b894'/><stop offset='1' stop-color='%2300d4a6' stop-opacity='0.5'/></linearGradient></defs><rect width='100%' height='100%' fill='url(%23g3)' opacity='0.06'/><g fill='none' stroke='%2300b894' stroke-opacity='0.08'><path d='M0 40 q40 -30 80 0 t80 0 t80 0'</path></g></svg>");background-repeat:no-repeat;background-position:center}

    .widget{padding:14px;border-radius:10px;background:linear-gradient(180deg,#fff,rgba(0,184,148,0.02))}
    label{display:block;font-size:13px;color:var(--muted);margin-bottom:6px}
    input,select,textarea{width:100%;padding:8px;border-radius:8px;border:1px solid rgba(2,48,43,0.06);margin-bottom:8px}
    button{background:var(--accent);color:white;padding:8px 12px;border-radius:8px;border:0;cursor:pointer}
    .output{white-space:pre-wrap;background:rgba(2,48,43,0.03);padding:10px;border-radius:8px;font-size:14px}
  </style>
</head>
<body>
