  <script>
    // reveal logic
    (function(){
      var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var nodes = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){nodes.forEach(function(n){n.classList.add('visible')});return}
      var io = new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}});},{threshold:0.12});
      nodes.forEach(function(n){io.observe(n)});
    })();

    // planner widget in programs
    (function(){
      var build = document.getElementById('p_build');
      var copy = document.getElementById('p_copy');
      var out = document.getElementById('p_output');
      function make(){
        var goal = document.getElementById('p_goal').value.trim();
        var habit = document.getElementById('p_habit').value.trim();
        var weeks = document.getElementById('p_weeks').value;
        var notes = document.getElementById('p_notes').value.trim();
        if(!goal){out.textContent='Add a short objective to create a plan.';return}
        var s = [];
        s.push('Journey plan');
        s.push('Objective: ' + goal);
        s.push('Tiny habit: ' + (habit || '—'));
        s.push('Duration: ' + weeks + ' weeks');
        s.push('Weekly checkpoints: brief group review + one paired reflection');
        if(notes) s.push('Notes: ' + notes);
        s.push('\nBring this summary to intake to help match you to a cohort seat.');
        out.textContent = s.join('\n');
      }
      build.addEventListener('click',make);
      copy.addEventListener('click',function(){
        var text = out.textContent;
        navigator.clipboard && navigator.clipboard.writeText(text).then(function(){
          copy.textContent='Copied'; setTimeout(function(){copy.textContent='Copy'},1400);
        },function(){alert('Unable to copy')});
      });
    })();
  </script>
